import { useListCollection } from '@ark-ui/solid/collection';
import { useFilter } from '@ark-ui/solid/locale';
import {
  ChevronDown,
  CircleHelp,
  FolderKanban,
  LayoutDashboard,
  Menu as MenuIcon,
  Orbit as OrbitIcon,
  Search,
  Settings,
  UserRound,
} from 'lucide-solid';
import { For } from 'solid-js';
import { Avatar, AvatarFallback, AvatarImage } from '@/registry/solid/ui/avatar';
import { Button } from '@/registry/solid/ui/button';
import {
  CommandPalette,
  CommandPaletteCombobox,
  CommandPaletteEmpty,
  CommandPaletteItem,
  CommandPaletteItemDescription,
  CommandPaletteItemGroup,
  CommandPaletteItemGroupLabel,
  CommandPaletteItemIcon,
  CommandPaletteItemLabel,
  CommandPaletteItemText,
  CommandPaletteList,
  CommandPalettePanel,
  CommandPaletteSearch,
  CommandPaletteTrigger,
} from '@/registry/solid/ui/command-palette';
import {
  Menu,
  MenuTrigger,
  MenuPositioner,
  MenuContent,
  MenuViewport,
  MenuItem,
  MenuItemGroup,
  MenuItemGroupLabel,
} from '@/registry/solid/ui/menu';
import styles from './app-header.module.css';

const navigation = [
  { label: 'Overview', href: '#overview' },
  { label: 'Projects', href: '#projects' },
  { label: 'Team', href: '#team' },
];

const commandItems = [
  {
    id: 'overview',
    section: 'Navigate',
    label: 'Overview',
    description: 'View your workspace summary',
    href: '#overview',
    icon: <LayoutDashboard />,
  },
  {
    id: 'projects',
    section: 'Navigate',
    label: 'Projects',
    description: 'Browse active projects',
    href: '#projects',
    icon: <FolderKanban />,
  },
  {
    id: 'team',
    section: 'Navigate',
    label: 'Team',
    description: 'See your teammates',
    href: '#team',
    icon: <UserRound />,
  },
  {
    id: 'workspace-settings',
    section: 'Workspace',
    label: 'Workspace settings',
    description: 'Manage your workspace preferences',
    href: '#workspace-settings',
    icon: <Settings />,
  },
  {
    id: 'help',
    section: 'Workspace',
    label: 'Help and support',
    description: 'Find product help',
    href: '#help',
    icon: <CircleHelp />,
  },
];

const account = {
  name: 'Alex Morgan',
  role: 'Product designer',
  email: 'alex@acme.studio',
  image:
    'https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&w=128&h=128&q=80',
};

export function AppHeader() {
  const filterOptions = useFilter({ sensitivity: 'base' });
  const collectionState = useListCollection({
    initialItems: commandItems,
    itemToString: (item) => `${item.label} ${item.description} ${item.section}`,
    itemToValue: (item) => item.href,
    filter: (itemText, filterText) => filterOptions().contains(itemText, filterText),
    groupBy: (item) => item.section,
  });

  return (
    <CommandPalette
      aria-label="Search workspace"
      onOpenChange={(details) => {
        if (!details.open) {
          collectionState.filter('');
        }
      }}
    >
      <header class={styles.root}>
        <div class={styles.leading}>
          <a class={styles.brand} href="#overview" aria-label="Orbit home">
            <span class={styles.brandMark} aria-hidden>
              <OrbitIcon />
            </span>
            <span class={styles.brandName}>Orbit</span>
          </a>

          <span class={styles.workspace}>
            <span class={styles.statusDot} aria-hidden />
            Acme Studio
          </span>
        </div>

        <nav class={styles.navigation} aria-label="Primary navigation">
          <For each={navigation}>
            {(item, index) => (
              <a
                class={styles.navigationLink}
                href={item.href}
                aria-current={index() === 0 ? 'page' : undefined}
              >
                {item.label}
              </a>
            )}
          </For>
        </nav>

        <div class={styles.actions}>
          <span class={styles.mobileNavigation}>
            <Menu positioning={{ placement: 'bottom-end', gutter: 10 }}>
              <MenuTrigger
                asChild={(props) => (
                  <Button
                    {...props()}
                    variant="ghost"
                    size="icon-sm"
                    aria-label="Open navigation"
                  />
                )}
              >
                <MenuIcon />
              </MenuTrigger>
              <MenuPositioner>
                <MenuContent class={styles.mobileNavigationMenu}>
                  <MenuViewport>
                    <MenuItemGroup>
                      <MenuItemGroupLabel>Navigation</MenuItemGroupLabel>
                      <For each={navigation}>
                        {(item, index) => (
                          <MenuItem
                            value={item.href}
                            asChild={(props) => (
                              <a
                                {...props()}
                                href={item.href}
                                aria-current={index() === 0 ? 'page' : undefined}
                              />
                            )}
                          >
                            {item.label}
                          </MenuItem>
                        )}
                      </For>
                    </MenuItemGroup>
                  </MenuViewport>
                </MenuContent>
              </MenuPositioner>
            </Menu>
          </span>

          <CommandPaletteTrigger
            asChild={(props) => (
              <Button
                {...props()}
                class={styles.searchTrigger}
                variant="ghost"
                size="icon-sm"
                aria-label="Search"
              />
            )}
          >
            <Search aria-hidden />
          </CommandPaletteTrigger>

          <Menu positioning={{ placement: 'bottom-end', gutter: 10 }}>
            <MenuTrigger
              asChild={(props) => (
                <Button
                  {...props()}
                  class={styles.accountTrigger}
                  variant="ghost"
                  size="sm"
                  aria-label={`Open ${account.name}'s account menu`}
                />
              )}
            >
              <Avatar class={styles.avatar} size="sm">
                <AvatarImage src={account.image} alt="" />
                <AvatarFallback>{account.name.slice(0, 1)}</AvatarFallback>
              </Avatar>
              <span class={styles.accountDetails}>
                <strong>{account.name}</strong>
                <span>{account.role}</span>
              </span>
              <ChevronDown class={styles.accountChevron} aria-hidden />
            </MenuTrigger>
            <MenuPositioner>
              <MenuContent class={styles.accountMenu}>
                <MenuViewport>
                  <MenuItemGroup>
                    <MenuItemGroupLabel class={styles.accountSummary}>
                      <strong>{account.name}</strong>
                      <span>{account.email}</span>
                    </MenuItemGroupLabel>
                    <MenuItem
                      value="profile"
                      asChild={(props) => (
                        <a {...props()} class={styles.menuLink} href="#profile" />
                      )}
                    >
                      <UserRound aria-hidden />
                      Profile
                    </MenuItem>
                    <MenuItem
                      value="workspace-settings"
                      asChild={(props) => (
                        <a {...props()} class={styles.menuLink} href="#workspace-settings" />
                      )}
                    >
                      <Settings aria-hidden />
                      Workspace settings
                    </MenuItem>
                    <MenuItem
                      value="help"
                      asChild={(props) => <a {...props()} class={styles.menuLink} href="#help" />}
                    >
                      <CircleHelp aria-hidden />
                      Help and support
                    </MenuItem>
                  </MenuItemGroup>
                </MenuViewport>
              </MenuContent>
            </MenuPositioner>
          </Menu>
        </div>
      </header>

      <CommandPalettePanel class={styles.commandPalette}>
        <CommandPaletteCombobox
          collection={collectionState.collection()}
          onInputValueChange={(details) => collectionState.filter(details.inputValue)}
          onSelect={(details) => {
            window.location.hash = details.itemValue;
          }}
        >
          <CommandPaletteSearch placeholder="Search workspace..." />
          <CommandPaletteList>
            <CommandPaletteEmpty>No commands found.</CommandPaletteEmpty>
            <For each={collectionState.collection().group()}>
              {([section, items]) => (
                <CommandPaletteItemGroup>
                  <CommandPaletteItemGroupLabel>{section}</CommandPaletteItemGroupLabel>
                  <For each={items}>
                    {(item) => (
                      <CommandPaletteItem item={item}>
                        <CommandPaletteItemIcon>{item.icon}</CommandPaletteItemIcon>
                        <CommandPaletteItemText>
                          <CommandPaletteItemLabel>{item.label}</CommandPaletteItemLabel>
                          <CommandPaletteItemDescription>
                            {item.description}
                          </CommandPaletteItemDescription>
                        </CommandPaletteItemText>
                      </CommandPaletteItem>
                    )}
                  </For>
                </CommandPaletteItemGroup>
              )}
            </For>
          </CommandPaletteList>
        </CommandPaletteCombobox>
      </CommandPalettePanel>
    </CommandPalette>
  );
}

.root {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: center;
  gap: var(--moduix-spacing-4);
  width: 100%;
  min-height: 4.5rem;
  padding: var(--moduix-spacing-2);
  border: var(--moduix-border-width-sm) solid
    color-mix(in oklab, var(--moduix-color-border) 72%, transparent);
  border-radius: calc(var(--moduix-radius-xl) + var(--moduix-spacing-2));
  background-color: color-mix(in oklab, var(--moduix-color-card) 96%, transparent);
  box-shadow: var(--moduix-shadow-sm);
  color: var(--moduix-color-card-foreground);
}

.leading,
.actions {
  display: flex;
  align-items: center;
  min-width: 0;
}

.leading {
  gap: var(--moduix-spacing-3);
}

.brand {
  display: inline-flex;
  align-items: center;
  flex-shrink: 0;
  gap: var(--moduix-spacing-2);
  color: inherit;
  text-decoration: none;

  &:focus-visible {
    outline: var(--moduix-focus-ring-width) solid var(--moduix-color-ring);
    outline-offset: var(--moduix-focus-ring-offset);
    border-radius: var(--moduix-radius-md);
  }
}

.brandMark {
  display: grid;
  place-items: center;
  width: 2.25rem;
  height: 2.25rem;
  border-radius: var(--moduix-radius-lg);
  background-color: var(--moduix-color-foreground);
  box-shadow: var(--moduix-shadow-sm);
  color: var(--moduix-color-background);

  & > svg {
    width: 1.125rem;
    height: 1.125rem;
    stroke-width: 2.25;
  }
}

.brandName {
  font-size: var(--moduix-text-md);
  font-weight: var(--moduix-weight-semibold);
  letter-spacing: -0.025em;
}

.workspace {
  display: inline-flex;
  align-items: center;
  min-width: 0;
  gap: var(--moduix-spacing-2);
  padding-inline-start: var(--moduix-spacing-3);
  border-inline-start: var(--moduix-border-width-sm) solid var(--moduix-color-border);
  color: var(--moduix-color-muted-foreground);
  font-size: var(--moduix-text-sm);
  line-height: var(--moduix-line-height-text-sm);
  white-space: nowrap;
}

.statusDot {
  width: var(--moduix-spacing-2);
  height: var(--moduix-spacing-2);
  flex-shrink: 0;
  border-radius: var(--moduix-radius-full);
  background-color: var(--moduix-color-primary);
  box-shadow: 0 0 0 var(--moduix-spacing-0-5)
    color-mix(in oklab, var(--moduix-color-primary) 18%, transparent);
}

.navigation {
  display: flex;
  align-items: center;
  gap: var(--moduix-spacing-0-5);
  padding: var(--moduix-spacing-1);
  border-radius: var(--moduix-radius-full);
  background-color: color-mix(
    in oklab,
    var(--moduix-color-muted) 82%,
    var(--moduix-color-background) 18%
  );
}

.navigationLink {
  display: inline-flex;
  align-items: center;
  min-height: 2.25rem;
  padding-inline: var(--moduix-spacing-3);
  border-radius: var(--moduix-radius-full);
  color: var(--moduix-color-muted-foreground);
  font-size: var(--moduix-text-sm);
  font-weight: var(--moduix-weight-medium);
  text-decoration: none;
  transition:
    background-color 150ms ease,
    box-shadow 150ms ease,
    color 150ms ease;

  &:hover {
    color: var(--moduix-color-foreground);
  }

  &[aria-current='page'] {
    background-color: var(--moduix-color-card);
    box-shadow: var(--moduix-shadow-sm);
    color: var(--moduix-color-foreground);
  }

  &:focus-visible {
    outline: var(--moduix-focus-ring-width) solid var(--moduix-color-ring);
    outline-offset: var(--moduix-focus-ring-offset);
  }
}

.actions {
  justify-content: flex-end;
  gap: var(--moduix-spacing-1);
}

.searchTrigger,
.accountTrigger {
  border-radius: var(--moduix-radius-full);
}

.searchTrigger {
  color: var(--moduix-color-muted-foreground);
}

.searchTrigger > svg,
.accountChevron,
.menuLink > svg {
  width: 1rem;
  height: 1rem;
  flex-shrink: 0;
}

.accountTrigger {
  gap: var(--moduix-spacing-2);
  height: auto;
  padding: var(--moduix-spacing-1) var(--moduix-spacing-2) var(--moduix-spacing-1)
    var(--moduix-spacing-1);
}

.avatar {
  flex-shrink: 0;
  box-shadow: 0 0 0 var(--moduix-border-width-sm) var(--moduix-color-border);
}

.accountDetails,
.accountSummary {
  display: grid;
  min-width: 0;
  text-align: start;
}

.accountDetails {
  gap: var(--moduix-spacing-0-5);

  strong,
  span {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  strong {
    font-size: var(--moduix-text-sm);
    font-weight: var(--moduix-weight-medium);
    line-height: 1;
  }

  span {
    color: var(--moduix-color-muted-foreground);
    font-size: var(--moduix-text-xs);
    font-weight: var(--moduix-weight-regular);
    line-height: 1;
  }
}

.accountChevron {
  color: var(--moduix-color-muted-foreground);
}

.mobileNavigation {
  display: none;
}

.mobileNavigationMenu {
  --moduix-menu-popup-min-width: 12rem;
}

.commandPalette {
  --moduix-command-palette-width: min(34rem, calc(100vw - 2rem));
}

.accountMenu {
  --moduix-menu-popup-min-width: 15rem;
}

.accountSummary {
  gap: var(--moduix-spacing-0-5);
  padding-block: var(--moduix-spacing-1);

  strong {
    color: var(--moduix-color-foreground);
    font-size: var(--moduix-text-sm);
    font-weight: var(--moduix-weight-medium);
    line-height: var(--moduix-line-height-text-sm);
  }

  span {
    overflow: hidden;
    color: var(--moduix-color-muted-foreground);
    font-size: var(--moduix-text-xs);
    font-weight: var(--moduix-weight-regular);
    line-height: var(--moduix-line-height-text-xs);
    text-overflow: ellipsis;
    white-space: nowrap;
  }
}

.menuLink {
  display: flex;
  align-items: center;
  gap: var(--moduix-spacing-2);
}

@media (width < 64rem) {
  .workspace {
    display: none;
  }
}

@media (width < 48rem) {
  .root {
    grid-template-columns: minmax(0, 1fr) auto;
    gap: var(--moduix-spacing-2);
  }

  .navigation {
    display: none;
  }

  .mobileNavigation {
    display: inline-flex;
  }
}

@media (width < 36rem) {
  .root {
    border-radius: var(--moduix-radius-xl);
  }

  .accountDetails,
  .accountChevron {
    display: none;
  }

  .accountTrigger {
    padding: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .navigationLink {
    transition: none;
  }
}
